<?php /** @var array{rows:list<array<string,mixed>>,counts:array<string,int>} $listing */ /** @var array<string,mixed> $filters */ /** @var array<string,string> $statuses */ ?>
<div class="page-head"><div><p class="eyebrow">Compliance &amp; legal</p><h1>Data deletion requests</h1></div><a class="btn btn-ghost" href="/data-deletion" target="_blank" rel="noopener">Public request page</a></div>
<div class="stat-grid"><?php foreach (['verified' => 'To review', 'needs_clarification' => 'Waiting for the requester', 'approved' => 'Approved: to process', 'awaiting_verification' => 'Not confirmed yet', 'completed' => 'Completed'] as $k => $l) : ?><a class="stat" href="?status=<?= e($k) ?>"><span class="stat-n"><?= e($listing['counts'][$k] ?? 0) ?></span><span class="stat-l"><?= e($l) ?></span></a><?php endforeach; ?></div>
<form method="get" class="toolbar" role="search"><div class="field"><label for="q">Search</label><input id="q" name="q" value="<?= e($filters['q']) ?>" placeholder="Reference, name or email"></div>
    <div class="field"><label for="s">Status</label><select id="s" name="status"><option value="">All</option><?php foreach ($statuses as $c => $l) : ?><option value="<?= e($c) ?>"<?= $filters['status'] === $c ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
    <div class="field"><button class="btn btn-ghost" type="submit">Filter</button></div></form>
<div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Reference</th><th>Requester</th><th>Status</th><th>Received</th><th></th></tr></thead><tbody>
<?php foreach ($listing['rows'] as $r) : ?><tr><td><a href="/admin/compliance/deletion/<?= e($r['id']) ?>"><strong><?= e($r['reference']) ?></strong></a></td><td><?= e($r['requester_name']) ?><br><span class="muted small"><?= e($r['requester_email']) ?></span></td>
    <td><?= e($statuses[$r['status']] ?? $r['status']) ?></td><td><?= e(local_time($r['created_at'])) ?></td><td><a href="/admin/compliance/deletion/<?= e($r['id']) ?>">Open</a></td></tr><?php endforeach; ?>
<?php if ($listing['rows'] === []) : ?><tr><td colspan="5" class="muted">No requests.</td></tr><?php endif; ?></tbody></table></div></div>
